@contextmanager
def publication_identity_fence(root: Path, *, nonblocking: bool=False) -> Iterator[None]:
    if os.name != 'posix':
        yield
        return
    import fcntl
    path = root / '.compaction-publication-handoff.lock'
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_CLOEXEC | os.O_NOFOLLOW, 384)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.getuid():
            raise ValueError('Unsafe compaction publication identity fence')
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | (fcntl.LOCK_NB if nonblocking else 0))
        except BlockingIOError as error:
            from .errors import RelationViolationError
            raise RelationViolationError('Canonical session identity is publishing; retry the identity change') from error
        yield
    finally:
        os.close(fd)

